// Gate: the release being deployed (or another release of the same build) is the one running in
// every lower environment of the application. Runs in the code-exec sandbox: `inputs` are this
// step's inputs, and the only reachable host is api.nullplatform.com.
const EXPLAIN = "**What it checks:** the release you are deploying (or another release of the same build) is the one currently running in every lower environment of this application.\n\n**Why:** every change goes through the lower environments before production, so it is tested with the real integrations before it reaches users.\n\n**How to fix:** deploy the same release to the environments listed as missing (and finish their traffic switch), then deploy to production again.";

const p = inputs.params || {};
const dimension = String(p.dimension || 'environment');
const required = String(p.required_values || '').split(',').map((s) => s.trim()).filter(Boolean);
const releaseId = String(p.release_id || '');
const buildId = p.build_id ? String(p.build_id) : '';
const appId = String(p.application_id || '');

const out = (status, message, extra) => ({
  status,
  message,
  details: Object.assign({ markdown: EXPLAIN, dimension, required_values: required, release_id: releaseId, build_id: buildId || null }, extra || {}),
});

if (required.length === 0) return out('failed', 'Checklist misconfigured: required_values is empty.');
if (!releaseId || !appId) return out('failed', 'The dispatch did not include application_id / release_id.');

const tok = await fetch('https://api.nullplatform.com/token', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ api_key: inputs.np_api_key }),
});
if (!tok.ok) throw new Error('NP token exchange failed: ' + tok.status);
const token = (await tok.json()).access_token;
const np = async (path) => {
  const r = await fetch('https://api.nullplatform.com' + path, { headers: { authorization: 'Bearer ' + token } });
  if (!r.ok) throw new Error('NP GET ' + path + ' -> ' + r.status);
  return r.json();
};

// Active scopes of the application (paginated).
const scopes = [];
for (let offset = 0; ; offset += 100) {
  const page = await np(`/scope?application_id=${appId}&status=active&limit=100&offset=${offset}`);
  scopes.push(...(page.results || []));
  if (offset + 100 >= ((page.paging && page.paging.total) || 0)) break;
}

// The scope LIST does not fill active_deployment: read each scope by id.
const releases = {};
const release = async (id) => {
  if (!(id in releases)) releases[id] = await np('/release/' + id).catch(() => null);
  return releases[id];
};

const evidence = {};
const missing = [];
for (const value of required) {
  const envScopes = scopes.filter((s) => (s.dimensions || {})[dimension] === value);
  const rows = [];
  let match = null;
  for (const s of envScopes) {
    const full = await np('/scope/' + s.id);
    const activeId = full.active_deployment || full.current_active_deployment;
    if (!activeId) { rows.push({ scope_id: s.id, scope: s.name, deployment_id: null }); continue; }
    const dep = await np('/deployment/' + activeId);
    const rel = await release(String(dep.release_id));
    const row = {
      scope_id: s.id,
      scope: s.name,
      deployment_id: activeId,
      release_id: String(dep.release_id),
      semver: rel && rel.semver,
      build_id: rel && rel.build_id != null ? String(rel.build_id) : null,
    };
    rows.push(row);
    if (row.release_id === releaseId || (buildId && row.build_id === buildId)) { match = row; break; }
  }
  if (match) { evidence[value] = { ok: true, matched: match }; continue; }

  let reason;
  if (envScopes.length === 0) reason = 'no active scopes';
  else if (rows.every((r) => !r.deployment_id)) reason = 'no scope has a running deployment';
  else reason = 'runs ' + [...new Set(rows.filter((r) => r.deployment_id).map((r) => r.semver || 'release ' + r.release_id))].join(', ');
  missing.push(value + ': ' + reason);
  evidence[value] = { ok: false, reason, scopes: rows };
}

const candidate = await release(releaseId);
const label = (candidate && candidate.semver) || releaseId;
if (missing.length === 0) return out('passed', `Release ${label} is running in ${required.join(', ')}.`, { evidence });
return out('failed', `Release ${label} is not running in every lower environment (${missing.join('; ')}). Deploy it there first.`, {
  evidence,
  missing: missing.map((m) => m.split(':')[0]),
});
